function parseSheet(name){
  const rows = sheetRows(name)
  let curDate = null, curLabel = null, blocks = [], venues = {}
  const out = []
  for(const {r,cells} of rows){
    const g = (c)=> (cells[String(c)]||'').trim()
    const ks = Object.keys(cells).map(Number).sort((a,b)=>a-b)
    const venueCols = ks.filter(k=>g(k)==='Venue')
    if(venueCols.length){ blocks = venueCols; venues = {}; continue }
    // date / section marker row: single cell in col A (or first col)
    if(ks.length===1){
      const v = g(ks[0])
      if(/^\d{5}$/.test(v)){ curDate = excelDate(v); curLabel = curDate; continue }
      if(/^\d{1,2}\s+\w+\s+\d{4}/.test(v)){ curLabel = v; curDate = v; continue }
      if(/to be scheduled/i.test(v)){ curLabel='TO_BE_SCHEDULED'; curDate=null; continue }
      // e.g. 'Lunch' alone, or notes
      out.push({r, note:v, date:curLabel})
      continue
    }
    if(!blocks.length) { out.push({r, note: ks.map(k=>g(k)).join(' | '), date:curLabel}); continue }
    for(const b of blocks){
      const venue=g(b), time=g(b+1), dur=g(b+2), acct=g(b+3), title=g(b+4), sup=g(b+5), se=g(b+6), stud=g(b+7)
      if(venue) venues[b]=venue
      if(!time && !acct) continue
      if(/^lunch$/i.test(time) || /^lunch$/i.test(venue)) continue
      out.push({r, block:colname(b), date:curLabel, venue: venues[b]||venue, time, dur, acct, title, sup, se, stud})
    }
  }
  return out
}
