function parseSheet2(name){
  const rows = sheetRows(name)
  let curLabel = null, blocks = [], venues = {}
  const out = []
  const FIELD = {'Venue':'venue','Time':'time','Date/Time':'time','Date':'date2','Presentation Time':'dur','Account No.':'acct','Project Title':'title','Supervisor(s)':'sup','Supervisor':'sup','Second Examiner':'se','Student Name':'stud'}
  for(const {r,cells} of rows){
    const g = (c)=> (cells[String(c)]||'').trim()
    const ks = Object.keys(cells).map(Number).sort((a,b)=>a-b)
    const venueCols = ks.filter(k=>g(k)==='Venue')
    if(venueCols.length){
      // build blocks: for each venue col, collect following header cells until next venue col or gap
      blocks = venueCols.map((vc,i)=>{
        const end = i+1<venueCols.length ? venueCols[i+1] : Infinity
        const map = {}
        for(const k of ks){ if(k>=vc && k<end){ const f = FIELD[g(k)]; if(f) map[f]=k; else map['_unk_'+k]=k } }
        return {start:vc, map, headerRow:r}
      })
      venues = {}
      continue
    }
    if(ks.length===1){
      const v=g(ks[0])
      if(/^\d{5}$/.test(v)){ curLabel=excelDate(v); continue }
      if(/^\d{1,2}\s+\w+\s+\d{4}/.test(v)){ curLabel=normDate(v); continue }
      if(/to be scheduled/i.test(v)){ curLabel='TO_BE_SCHEDULED'; continue }
      out.push({r, note:v, date:curLabel}); continue
    }
    if(!blocks.length){ out.push({r, note:ks.map(k=>g(k)).join(' | '), date:curLabel}); continue }
    for(const b of blocks){
      const rec = {}
      for(const f in b.map) rec[f] = g(b.map[f])
      if(rec.venue) venues[b.start]=rec.venue
      if(!rec.acct && !rec.time) continue
      if(/^lunch$/i.test(rec.time||'') || /^lunch$/i.test(rec.venue||'')) continue
      out.push({r, block:colname(b.start), date:curLabel, ...rec, venue: rec.venue || venues[b.start] || ''})
    }
  }
  return out
}
